const body = $json.body ?? $json;
const supportedLanguages = ['typescript', 'javascript', 'python', 'php'];
const taskDescription = String(body.task_description ?? '').trim();
const code = String(body.code ?? '').trim();
const language = String(body.language ?? '').trim().toLowerCase();
const model = typeof body.model === 'string' && body.model.trim() ? body.model.trim() : 'openai/gpt-4o-mini';
const promptVersion = Number.isInteger(body.prompt_version) && body.prompt_version > 0 ? body.prompt_version : undefined;
if (!taskDescription) throw new Error('O campo task_description e obrigatorio.');
if (!code) throw new Error('O campo code e obrigatorio.');
if (!supportedLanguages.includes(language)) throw new Error(`Linguagem nao suportada para compliance: ${language || '(vazia)'}.`);
const inputPayload = { task_description: taskDescription, code, language };
if (promptVersion !== undefined) inputPayload.prompt_version = promptVersion;
if (body.model !== undefined) inputPayload.model = model;
const requestState = { flow_type: 'compliance', input_payload: inputPayload, model, started_at_ms: Date.now() };
function normalizeForHash(value) { if (Array.isArray(value)) return value.map(normalizeForHash); if (value && typeof value === 'object') { const normalized = {}; for (const key of Object.keys(value).sort()) normalized[key] = normalizeForHash(value[key]); return normalized; } return value; }
function createPayloadHash(text) { let h1 = 0xdeadbeef ^ text.length; let h2 = 0x41c6ce57 ^ text.length; for (let index = 0; index < text.length; index += 1) { const ch = text.charCodeAt(index); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return `${(h2 >>> 0).toString(16).padStart(8, '0')}${(h1 >>> 0).toString(16).padStart(8, '0')}`; }
function sql(value) { return String(value).replaceAll("'", "''"); }
const normalizedPayloadText = JSON.stringify(normalizeForHash(inputPayload));
const requestHash = createPayloadHash(normalizedPayloadText);
const stateJson = JSON.stringify(requestState);
const inputJson = JSON.stringify(inputPayload);
const cacheLookupQuery = `WITH request_data AS (
  SELECT '${sql(inputJson)}'::jsonb AS input_payload,
         '${sql(stateJson)}'::jsonb AS request_state,
         '${sql(requestHash)}'::text AS request_hash
), cached AS (
  SELECT id, output_payload
  FROM executions
  WHERE flow_type = 'compliance'
    AND status = 'success'
    AND request_hash = (SELECT request_hash FROM request_data)
  ORDER BY created_at DESC
  LIMIT 1
)
SELECT (SELECT request_hash FROM request_data) AS request_hash,
       EXISTS(SELECT 1 FROM cached) AS cache_hit,
       (SELECT id::text FROM cached) AS source_execution_id,
       (SELECT output_payload FROM cached) AS output_payload,
       (SELECT request_state FROM request_data) AS request_state;`;
return [{ json: { request_state: requestState, cache_lookup_query: cacheLookupQuery } }];

const prepared = $('Prepare Compliance Request').first().json;
if (!prepared?.cache_lookup_query) throw new Error('Cache lookup query was not prepared.');
return [{ json: prepared }];

const state = $json.request_state;
const requestHash = String($json.request_hash);
const sourceExecutionId = String($json.source_execution_id);
const outputPayload = $json.output_payload;
const durationMs = Math.max(0, Date.now() - Number(state.started_at_ms ?? Date.now()));
function sql(value) { return String(value).replaceAll("'", "''"); }
const stateJson = JSON.stringify(state);
const inputJson = JSON.stringify(state.input_payload);
const outputJson = JSON.stringify(outputPayload);
const query = `INSERT INTO executions (id, flow_type, status, input_payload, output_payload, request_hash, cache_hit, source_execution_id, duration_ms)
VALUES (gen_random_uuid(), 'compliance', 'success', '${sql(inputJson)}'::jsonb, '${sql(outputJson)}'::jsonb, '${sql(requestHash)}', true, '${sql(sourceExecutionId)}'::uuid, ${durationMs})
RETURNING id::text AS execution_id, output_payload AS response, '${sql(requestHash)}' AS request_hash, '${sql(sourceExecutionId)}' AS source_execution_id, ${durationMs}::integer AS duration_ms, '${sql(stateJson)}'::jsonb AS request_state;`;
return [{ json: { create_cache_hit_query: query } }];

const executionId = String($json.execution_id);
const requestHash = String($json.request_hash);
const sourceExecutionId = String($json.source_execution_id);
const response = $json.response;
const durationMs = Number($json.duration_ms ?? 0);
function sql(value) { return String(value).replaceAll("'", "''"); }
const inputPayload = JSON.stringify({ requestHash });
const outputPayload = JSON.stringify({ cacheHit: true, sourceExecutionId });
const responseJson = JSON.stringify(response);
const query = `WITH inserted AS (
  INSERT INTO execution_steps (execution_id, node_name, kind, status, input_payload, output_payload, duration_ms)
  VALUES ('${sql(executionId)}'::uuid, 'cache_lookup', 'cache', 'success', '${sql(inputPayload)}'::jsonb, '${sql(outputPayload)}'::jsonb, ${durationMs})
  RETURNING execution_id
)
SELECT '${sql(responseJson)}'::jsonb AS response;`;
return [{ json: { record_cached_step_query: query } }];

const state = $json.request_state;
const requestHash = String($json.request_hash);
function sql(value) { return String(value).replaceAll("'", "''"); }
const inputJson = JSON.stringify(state.input_payload);
const stateJson = JSON.stringify(state);
const query = `INSERT INTO executions (id, flow_type, status, input_payload, request_hash, cache_hit)
VALUES (gen_random_uuid(), 'compliance', 'pending', '${sql(inputJson)}'::jsonb, '${sql(requestHash)}', false)
RETURNING id::text AS execution_id, request_hash, '${sql(stateJson)}'::jsonb AS request_state;`;
return [{ json: { create_pending_query: query } }];

const state = $json.request_state;
const executionId = String($json.execution_id);
const requestHash = String($json.request_hash);
const durationMs = Math.max(0, Date.now() - Number(state.started_at_ms ?? Date.now()));
function sql(value) { return String(value).replaceAll("'", "''"); }
const stateJson = JSON.stringify(state);
const inputPayload = JSON.stringify({ requestHash });
const outputPayload = JSON.stringify({ cacheHit: false });
const query = `WITH inserted AS (
  INSERT INTO execution_steps (execution_id, node_name, kind, status, input_payload, output_payload, duration_ms)
  VALUES ('${sql(executionId)}'::uuid, 'cache_lookup', 'cache', 'success', '${sql(inputPayload)}'::jsonb, '${sql(outputPayload)}'::jsonb, ${durationMs})
  RETURNING execution_id
)
SELECT '${sql(executionId)}' AS execution_id, '${sql(requestHash)}' AS request_hash, '${sql(stateJson)}'::jsonb AS request_state;`;
return [{ json: { record_cache_step_query: query } }];

const state = $json.request_state;
const input = state.input_payload;
const executionId = String($json.execution_id);
const requestHash = String($json.request_hash);
const promptData = { agent: { role: 'Voce e um agente senior de Qualidade e Compliance de Software para o sistema CPJ-Cobranca. Sua missao e cruzar criterios de aceite da tarefa com o codigo implementado, avaliando aderencia, lacunas e riscos de regras financeiras, auditoria e BACEN.', instructions: ['Responda somente JSON valido com compliant, compliance_score, covered_requirements, missing_requirements, partial_requirements e verdict.', 'Analise task_description e extraia requisitos funcionais, regras de negocio e criterios de aceite.', 'Cruze cada requisito com o codigo buscando evidencia objetiva.', 'Use covered_requirements apenas para regras totalmente atendidas.', 'Use missing_requirements para regras ignoradas.', 'Use partial_requirements para regras implementadas pela metade.', 'compliance_score deve ser inteiro de 0 a 100.', 'compliant so deve ser true quando todos os criterios fundamentais estiverem cobertos.', 'verdict deve ser direto e explicar o que falta para aprovar a tarefa.'] } };
const stopWords = new Set(['apenas','cada','com','como','deve','para','pela','pelo','por','quando','que','sem','todos','toda','todo']);
function normalize(value) { return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); }
function cleanRequirementText(text) { return String(text).trim().replace(/^[-*]\s*/, '').replace(/^\d+[.)]\s*/, '').trim(); }
function extractRequirements(taskDescription) { const lineRequirements = String(taskDescription).split('\n').map((line, index) => ({ text: cleanRequirementText(line), line_hint: `linha ${index + 1}` })).filter((requirement) => requirement.text.length > 0); if (lineRequirements.length > 1) return lineRequirements; return String(taskDescription).split(/[.;]/).map((text) => ({ text: cleanRequirementText(text), line_hint: null })).filter((requirement) => requirement.text.length > 0); }
function hasTextualEvidence(requirement, normalizedCode) { const tokens = normalize(requirement).split(/\W+/).filter((token) => token.length >= 4 && !stopWords.has(token)); if (tokens.length === 0) return false; return tokens.some((token) => normalizedCode.includes(token)); }
function findPossibleMissingRequirements(requirements, code) { const normalizedCode = normalize(code); return requirements.filter((requirement) => !hasTextualEvidence(requirement.text, normalizedCode)).map((requirement) => ({ kind: 'possible_missing_requirement', requirement: requirement.text, confidence: 'low', description: 'Nao encontrei evidencia textual simples deste requisito no codigo.' })); }
const requirements = extractRequirements(input.task_description);
const findings = findPossibleMissingRequirements(requirements, input.code);
const toolResult = { requirements, findings };
const systemPrompt = `${promptData.agent.role}\n\nLinguagem: ${input.language}\n\nInstrucoes:\n${promptData.agent.instructions.map((instruction) => `- ${instruction}`).join('\n')}\n\nContrato de saida estruturada: responda somente JSON valido com este formato exato: {"compliant":false,"compliance_score":0,"covered_requirements":["string"],"missing_requirements":["string"],"partial_requirements":["string"],"verdict":"string"}.`;
const userPrompt = JSON.stringify({ task_description: input.task_description, codigo: input.code, requisitos_candidatos: requirements, sinais_deterministicos: findings }, null, 2);
return [{ json: { execution_id: executionId, request_hash: requestHash, request_state: state, language: input.language, tool_result: toolResult, compliance_system_prompt: systemPrompt, compliance_user_prompt: userPrompt } }];

const context = $('Requirements Extractor').first().json;
const raw = $json.output ?? $json.text ?? $json.response ?? $json;
function cleanJsonText(value) { return String(value ?? '').trim().replace(/^```json/i, '').replace(/^```/i, '').replace(/```$/i, '').trim(); }
function normalizeStringArray(value) { return Array.isArray(value) ? value.map(String).map((item) => item.trim()).filter(Boolean) : []; }
function normalizeCompliance(value) { const score = Number(value.compliance_score); const missing = normalizeStringArray(value.missing_requirements); const partial = normalizeStringArray(value.partial_requirements); const covered = normalizeStringArray(value.covered_requirements); return { compliant: Boolean(value.compliant) && missing.length === 0, compliance_score: Number.isInteger(score) ? Math.max(0, Math.min(100, score)) : (missing.length > 0 ? 60 : 80), covered_requirements: covered, missing_requirements: missing, partial_requirements: partial, verdict: String(value.verdict ?? 'Avaliacao de aderencia concluida.') }; }
function parseComplianceOutput(value) { if (typeof value === 'object' && value !== null && !Array.isArray(value)) return normalizeCompliance(value); const text = cleanJsonText(value); try { return normalizeCompliance(JSON.parse(text)); } catch { return { compliant: false, compliance_score: 50, covered_requirements: [], missing_requirements: ['O agente retornou conteudo fora do JSON estruturado esperado.'], partial_requirements: [], verdict: text.slice(0, 500) || 'Saida invalida do agente de compliance.' }; } }
function sql(value) { return String(value).replaceAll("'", "''"); }
function estimateTokens(value) { return Math.ceil(String(value ?? '').length / 4); }
const response = parseComplianceOutput(raw);
const executionId = context.execution_id;
const durationMs = Math.max(0, Date.now() - Number(context.request_state.started_at_ms ?? Date.now()));
const responseJson = JSON.stringify(response);
const promptText = [context.compliance_system_prompt, context.compliance_user_prompt].join('\n');
const completionText = JSON.stringify(response);
const promptTokens = estimateTokens(promptText);
const completionTokens = estimateTokens(completionText);
const totalTokens = promptTokens + completionTokens;
const inputCostUsd = Number(((promptTokens / 1000000) * 0.15).toFixed(8));
const outputCostUsd = Number(((completionTokens / 1000000) * 0.60).toFixed(8));
const costUsd = Number((inputCostUsd + outputCostUsd).toFixed(8));
const stepRows = [];
function addStep(nodeName, kind, inputPayload, outputPayload) { stepRows.push(`('${sql(executionId)}'::uuid, '${sql(nodeName)}', '${sql(kind)}', 'success', '${sql(JSON.stringify(inputPayload ?? null))}'::jsonb, '${sql(JSON.stringify(outputPayload ?? null))}'::jsonb, 0)`); }
addStep('requirements_extractor', 'tool', { task_description: context.request_state.input_payload.task_description, language: context.language }, context.tool_result);
addStep('compliance_agent', 'llm', { requirements: context.tool_result.requirements, findings: context.tool_result.findings }, response);
const persistSuccessQuery = `WITH updated AS (
  UPDATE executions
  SET status = 'success', output_payload = '${sql(responseJson)}'::jsonb, duration_ms = ${durationMs}, error_message = NULL, updated_at = NOW()
  WHERE id = '${sql(executionId)}'::uuid
  RETURNING id
), inserted_steps AS (
  INSERT INTO execution_steps (execution_id, node_name, kind, status, input_payload, output_payload, duration_ms)
  VALUES ${stepRows.join(',\n         ')}
  RETURNING execution_id
)
SELECT '${sql(responseJson)}'::jsonb AS response, '${sql(executionId)}' AS execution_id, ${durationMs}::integer AS duration_ms, ${promptTokens}::integer AS prompt_tokens, ${completionTokens}::integer AS completion_tokens, ${totalTokens}::integer AS total_tokens, ${costUsd}::numeric(12,8) AS cost_usd, ${inputCostUsd}::numeric(12,8) AS input_cost_usd, ${outputCostUsd}::numeric(12,8) AS output_cost_usd, '${sql(context.request_state.model)}' AS model_used;`;
const telemetryQuery = `INSERT INTO execution_telemetry (execution_id, provider, model_requested, model_used, prompt_tokens, completion_tokens, total_tokens, cost_usd, input_cost_usd, output_cost_usd, cache_read_tokens)
VALUES ('${sql(executionId)}'::uuid, 'openrouter', '${sql(context.request_state.model)}', '${sql(context.request_state.model)}', ${promptTokens}, ${completionTokens}, ${totalTokens}, ${costUsd}, ${inputCostUsd}, ${outputCostUsd}, NULL)
ON CONFLICT (execution_id) DO UPDATE SET model_used = EXCLUDED.model_used, prompt_tokens = EXCLUDED.prompt_tokens, completion_tokens = EXCLUDED.completion_tokens, total_tokens = EXCLUDED.total_tokens, cost_usd = EXCLUDED.cost_usd, input_cost_usd = EXCLUDED.input_cost_usd, output_cost_usd = EXCLUDED.output_cost_usd, cache_read_tokens = EXCLUDED.cache_read_tokens
RETURNING '${sql(responseJson)}'::jsonb AS response;`;
return [{ json: { response, persist_success_query: persistSuccessQuery, telemetry_query: telemetryQuery } }];

const normalized = $('Normalize Compliance Output').first().json;
if (!normalized?.telemetry_query) throw new Error('Telemetry query was not prepared.');
return [{ json: normalized }];
